"""Independent reference model (dict-based byte storage) for cross-checking."""
import json

MAXVAR = 4611686018427387903

class Err(Exception):
    def __init__(self, code, frame=None):
        Exception.__init__(self, code)
        self.code = code
        self.frame = frame


def allowed(level, fr):
    t = fr["type"]
    if t in ("PADDING", "PING"):
        return True
    if t in ("ACK", "CRYPTO"):
        return level in ("I", "H", "A")
    if t in ("STREAM", "RESET_STREAM", "STOP_SENDING"):
        return level in ("Z", "A")
    if t == "CLOSE":
        return (level in ("Z", "A")) if fr["app"] else True
    return False


def contains(sent, lo, hi):
    pos = lo
    for s, e in sent:
        if e < pos:
            continue
        if s > pos:
            return False
        if e >= hi:
            return True
        pos = e + 1
    return False


class Stream:
    def __init__(self):
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.data = {}
        self.delivered = bytearray()

    def copy(self):
        s = Stream()
        s.highest = self.highest
        s.final_size = self.final_size
        s.reset = self.reset
        s.stopped = self.stopped
        s.data = dict(self.data)
        s.delivered = bytearray(self.delivered)
        return s


class Crypto:
    def __init__(self):
        self.highest = 0
        self.data = {}
        self.contig = bytearray()

    def copy(self):
        c = Crypto()
        c.highest = self.highest
        c.data = dict(self.data)
        c.contig = bytearray(self.contig)
        return c


def contiguous(data):
    out = bytearray()
    o = 0
    while o in data:
        out.append(data[o])
        o += 1
    return out


def merge_bytes(data, offset, payload, policy):
    new = dict(data)
    for i, b in enumerate(payload):
        o = offset + i
        if o in new:
            if new[o] != b and policy == "reject":
                raise Err("PROTOCOL_VIOLATION")
        else:
            new[o] = b
    return new


class Ref:
    def __init__(self, trace):
        self.tr = trace
        self.cfg = trace["config"]
        self.res = {}

    def rec(self, e, p, status, reason, t, frame):
        self.res[(e, p)] = {
            "event": e, "packet": p, "status": status, "reason": reason,
            "at_ms": t, "frame": frame,
        }

    def run(self):
        cfg = self.cfg
        events = self.tr["events"]
        self.keys = {"I": "live", "H": "absent",
                     "Z": ("live" if cfg["early"] else "absent"), "A": "absent"}
        self.queue = []
        self.streams = {}
        self.crypto = {"I": Crypto(), "H": Crypto(), "A": Crypto()}
        self.total = 0
        self.pns = {"I": set(), "H": set(), "A": set()}
        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last = 0

        for ei, ev in enumerate(events):
            t = ev["t"]
            if self.state == "open" and cfg["idle_ms"] > 0:
                deadline = self.last + cfg["idle_ms"]
                if t >= deadline:
                    self.terminate("idle", "IDLE_TIMEOUT", deadline,
                                   {"event": ei, "packet": None, "frame": None}, None)
            if self.state != "open":
                if ev["op"] == "datagram":
                    for pi in range(len(ev["packets"])):
                        self.rec(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            if ev["op"] == "key":
                self.do_key(ei, ev, t)
            elif ev["op"] == "datagram":
                self.do_datagram(ei, ev, t)

        for q in self.queue:
            self.rec(q[0], q[1], "buffered", "NO_KEYS", q[6], None)
        self.queue = []
        return self.result()

    def terminate(self, st, code, t, src, pc):
        self.state = st
        self.code = code
        self.at_ms = t
        self.source = src
        self.peer_code = pc
        for q in list(self.queue):
            self.rec(q[0], q[1], "dropped", "CONNECTION_CLOSED", t, None)
        self.queue = []

    def do_key(self, ei, ev, t):
        level = ev["level"]
        if ev["action"] == "install":
            if self.keys[level] != "absent":
                return
            self.keys[level] = "live"
            pending = [q for q in self.queue if q[2] == level]
            self.queue = [q for q in self.queue if q[2] != level]
            for q in pending:
                if self.state != "open":
                    self.rec(q[0], q[1], "dropped", "CONNECTION_CLOSED", t, None)
                    continue
                self.do_packet(q[0], q[1], q[5], q[2], q[3], q[4], t, 1200, True)
            return
        self.keys[level] = "discarded"
        pending = [q for q in self.queue if q[2] == level]
        self.queue = [q for q in self.queue if q[2] != level]
        for q in pending:
            self.rec(q[0], q[1], "dropped", "KEYS_DISCARDED", t, None)

    def do_datagram(self, ei, ev, t):
        packets = ev["packets"]
        total = len(packets)
        for i, p in enumerate(packets):
            if p["level"] == "A" and i != total - 1:
                for j in range(total):
                    self.rec(ei, j, "dropped", "LAYOUT", t, None)
                return
        for i, p in enumerate(packets):
            if self.state != "open":
                self.rec(ei, i, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            self.do_packet(ei, i, p["frames"], p["level"], p["pn"], p["auth"], t,
                           ev["bytes"], False)

    def do_packet(self, e, p, frames, level, pn, auth, t, size, from_queue):
        cfg = self.cfg
        if not from_queue and level == "I" and size < 1200:
            self.rec(e, p, "dropped", "INITIAL_TOO_SMALL", t, None)
            return
        if level == "Z" and not cfg["early"]:
            self.rec(e, p, "dropped", "EARLY_REJECTED", t, None)
            return
        if self.keys[level] == "discarded":
            self.rec(e, p, "dropped", "KEYS_DISCARDED", t, None)
            return
        if self.keys[level] == "absent":
            if len(self.queue) < cfg["buffer_packets"]:
                self.queue.append((e, p, level, pn, auth, frames, t))
            else:
                self.rec(e, p, "dropped", "BUFFER_FULL", t, None)
            return
        if not auth:
            self.rec(e, p, "dropped", "AUTH", t, None)
            return
        space = "A" if level in ("Z", "A") else level
        if pn in self.pns[space]:
            self.rec(e, p, "duplicate", "DUPLICATE", t, None)
            return
        # preflight
        if not frames:
            self.terminate("closed", "FRAME_ENCODING_ERROR", t,
                           {"event": e, "packet": p, "frame": None}, None)
            self.rec(e, p, "error", "FRAME_ENCODING_ERROR", t, None)
            return
        for i, fr in enumerate(frames):
            if fr["type"] == "UNKNOWN":
                self.terminate("closed", "FRAME_ENCODING_ERROR", t,
                               {"event": e, "packet": p, "frame": i}, None)
                self.rec(e, p, "error", "FRAME_ENCODING_ERROR", t, i)
                return
            if not allowed(level, fr):
                self.terminate("closed", "PROTOCOL_VIOLATION", t,
                               {"event": e, "packet": p, "frame": i}, None)
                self.rec(e, p, "error", "PROTOCOL_VIOLATION", t, i)
                return
        # semantic on copies
        streams = {k: v.copy() for k, v in self.streams.items()}
        crypto = {k: v.copy() for k, v in self.crypto.items()}
        total = self.total
        try:
            for i, fr in enumerate(frames):
                ftype = fr["type"]
                if ftype in ("PADDING", "PING"):
                    continue
                if ftype == "ACK":
                    rr = fr["ranges"]
                    if not rr:
                        raise Err("FRAME_ENCODING_ERROR")
                    prev = None
                    for lo, hi in rr:
                        if lo > hi:
                            raise Err("FRAME_ENCODING_ERROR")
                        if prev is not None and lo <= prev + 1:
                            raise Err("FRAME_ENCODING_ERROR")
                        prev = hi
                    for lo, hi in rr:
                        if not contains(cfg["sent"][level], lo, hi):
                            raise Err("PROTOCOL_VIOLATION")
                    continue
                if ftype == "CRYPTO":
                    payload = bytes.fromhex(fr["data_hex"])
                    off = fr["offset"]
                    end = off + len(payload)
                    if end > MAXVAR:
                        raise Err("FRAME_ENCODING_ERROR")
                    if end > cfg["crypto_limit"]:
                        raise Err("CRYPTO_BUFFER_EXCEEDED")
                    c = crypto[level]
                    c.data = merge_bytes(c.data, off, payload, cfg["overlap"])
                    if end > c.highest:
                        c.highest = end
                    c.contig = contiguous(c.data)
                    continue
                if ftype == "STREAM":
                    sid = fr["id"]
                    if sid % 4 not in (0, 2):
                        raise Err("STREAM_STATE_ERROR")
                    lim = cfg["max_streams_bidi"] if sid % 4 == 0 else cfg["max_streams_uni"]
                    if sid // 4 + 1 > lim:
                        raise Err("STREAM_LIMIT_ERROR")
                    st = streams.get(sid)
                    if st is None:
                        st = Stream()
                        streams[sid] = st
                    payload = bytes.fromhex(fr["data_hex"])
                    off = fr["offset"]
                    fin = fr["fin"]
                    end = off + len(payload)
                    if end > MAXVAR:
                        raise Err("FRAME_ENCODING_ERROR")
                    if st.final_size is not None and (
                            end > st.final_size or (fin and end != st.final_size)):
                        raise Err("FINAL_SIZE_ERROR")
                    if fin and end < st.highest:
                        raise Err("FINAL_SIZE_ERROR")
                    if end > cfg["max_stream_data"]:
                        raise Err("FLOW_CONTROL_ERROR")
                    nh = max(st.highest, end)
                    delta = nh - st.highest
                    if total + delta > cfg["max_data"]:
                        raise Err("FLOW_CONTROL_ERROR")
                    if not st.reset:
                        st.data = merge_bytes(st.data, off, payload, cfg["overlap"])
                    st.highest = nh
                    total += delta
                    if fin and st.final_size is None:
                        st.final_size = end
                    if not st.reset:
                        newc = contiguous(st.data)
                        if len(newc) > len(st.delivered):
                            st.delivered = newc
                    continue
                if ftype == "RESET_STREAM":
                    sid = fr["id"]
                    if sid % 4 not in (0, 2):
                        raise Err("STREAM_STATE_ERROR")
                    lim = cfg["max_streams_bidi"] if sid % 4 == 0 else cfg["max_streams_uni"]
                    if sid // 4 + 1 > lim:
                        raise Err("STREAM_LIMIT_ERROR")
                    size = fr["final_size"]
                    st = streams.get(sid)
                    if st is None:
                        st = Stream()
                        streams[sid] = st
                    if st.final_size is not None and st.final_size != size:
                        raise Err("FINAL_SIZE_ERROR")
                    if size < st.highest:
                        raise Err("FINAL_SIZE_ERROR")
                    if size > cfg["max_stream_data"]:
                        raise Err("FLOW_CONTROL_ERROR")
                    nh = max(st.highest, size)
                    delta = nh - st.highest
                    if total + delta > cfg["max_data"]:
                        raise Err("FLOW_CONTROL_ERROR")
                    st.highest = nh
                    total += delta
                    st.final_size = size
                    st.reset = True
                    continue
                if ftype == "STOP_SENDING":
                    sid = fr["id"]
                    if sid % 4 != 0:
                        raise Err("STREAM_STATE_ERROR")
                    if sid // 4 + 1 > cfg["max_streams_bidi"]:
                        raise Err("STREAM_LIMIT_ERROR")
                    st = streams.get(sid)
                    if st is None:
                        st = Stream()
                        streams[sid] = st
                    st.stopped = True
                    continue
                if ftype == "CLOSE":
                    self.streams = streams
                    self.crypto = crypto
                    self.total = total
                    self.pns[space].add(pn)
                    self.last = t
                    self.terminate("closed",
                                   "PEER_APPLICATION_CLOSE" if fr["app"] else "PEER_TRANSPORT_CLOSE",
                                   t, {"event": e, "packet": p, "frame": i}, fr["code"])
                    self.rec(e, p, "accepted", "OK", t, None)
                    return
                raise Err("PROTOCOL_VIOLATION")
        except Err as err:
            fr_index = err.frame if err.frame is not None else i
            self.terminate("closed", err.code, t,
                           {"event": e, "packet": p, "frame": fr_index}, None)
            self.rec(e, p, "error", err.code, t, fr_index)
            return
        self.streams = streams
        self.crypto = crypto
        self.total = total
        self.pns[space].add(pn)
        self.last = t
        self.rec(e, p, "accepted", "OK", t, None)

    def result(self):
        packets = [self.res[k] for k in sorted(self.res)]
        streams = []
        for sid in sorted(self.streams):
            s = self.streams[sid]
            streams.append({"id": sid, "highest": s.highest, "final_size": s.final_size,
                            "reset": s.reset, "stopped": s.stopped,
                            "delivered_hex": bytes(s.delivered).hex()})
        crypto = [{"level": lv, "highest": self.crypto[lv].highest,
                   "contiguous_hex": bytes(self.crypto[lv].contig).hex()}
                  for lv in ("I", "H", "A")]
        return {
            "id": self.tr["id"],
            "packets": packets,
            "connection": {"state": self.state, "code": self.code, "at_ms": self.at_ms,
                           "source": self.source, "peer_code": self.peer_code,
                           "last_activity_ms": self.last},
            "keys": dict(self.keys),
            "received_total": self.total,
            "streams": streams,
            "crypto": crypto,
        }


def replay(doc):
    return {"version": 1, "results": [Ref(t).run() for t in doc["traces"]]}
